(()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)');if(!reduced.matches){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('motion-enter');observer.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('main>.section,.cta').forEach(e=>observer.observe(e));if(matchMedia('(hover:hover) and (pointer:fine)').matches)document.querySelectorAll('.feature-card,.tile,.purpose-grid article').forEach(el=>{el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect();el.style.setProperty('--rx',((.5-(e.clientY-r.top)/r.height)*4)+'deg');el.style.setProperty('--ry',(((e.clientX-r.left)/r.width-.5)*6)+'deg')});el.addEventListener('pointerleave',()=>{el.style.setProperty('--rx','0deg');el.style.setProperty('--ry','0deg')})})}
document.querySelectorAll('.story-carousel').forEach(track=>{const controls=track.nextElementSibling,items=[...track.children];let index=0;const move=delta=>{index=(index+delta+items.length)%items.length;track.scrollTo({left:items[index].offsetLeft-items[0].offsetLeft,behavior:reduced.matches?'instant':'smooth'});controls.querySelector('.carousel-status').textContent=`${index+1} / ${items.length}`};controls.querySelector('.carousel-prev').addEventListener('click',()=>move(-1));controls.querySelector('.carousel-next').addEventListener('click',()=>move(1));track.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();move(e.key==='ArrowLeft'?-1:1)}});track.addEventListener('scroll',()=>{const tr=track.getBoundingClientRect();index=items.reduce((best,item,i)=>Math.abs(item.getBoundingClientRect().left-tr.left)<Math.abs(items[best].getBoundingClientRect().left-tr.left)?i:best,0);controls.querySelector('.carousel-status').textContent=`${index+1} / ${items.length}`},{passive:true})});
document.querySelectorAll('[data-scroll-alerts]').forEach(b=>b.addEventListener('click',()=>requestAnimationFrame(()=>document.querySelector('.alerts-list')?.scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'center'}))));})();
